        if (curIsBuf0) {
          sW1(oc_off, kkk) = wval;
        } else {
          sW0(oc_off, kkk) = wval;
        }
      }
    }
    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      int p = p_idx[i];
      if (p >= P_total) continue;
      int od = od_arr[i];
      int oh = oh_arr[i];
      int ow = ow_arr[i];
      for (int kd = 0; kd < K; ++kd) {
        int num_d = od + padD - kd * dilD;
        if (num_d % strideD != 0) continue;
        int id = num_d / strideD;
        if (id < 0 || id >= D) continue;
        for (int kh = 0; kh < K; ++kh) {
          int num_h = oh + padH - kh * dilH;
          if (num_h % strideH != 0) continue;
          int ih = num_h / strideH;
          if (ih < 0 || ih >= H) continue;
          for (int kw = 0; kw < K; ++kw) {
            int num_w = ow + padW - kw * dilW;
            if (num_w % strideW != 0) continue;
            int iw = num_w / strideW;
            if (iw < 0 || iw >= Win) continue;
            int kkk = (kd * K + kh) * K + kw;
            float xval = (float)mX(ic, id, ih, iw);
            #pragma unroll
            for (int oc_off = 0; oc_off < OcTile; ++oc_off) {
              float wval = curIsBuf0 ? (float)sW0(oc_off, kkk) : (float)sW1(oc_off, kkk);
              acc[oc_off][i] += xval * wval;
            }
          }
        }
      }
    }
    __syncthreads();
  }

  // Store results
  #pragma unroll
  for (int oc_off = 0; oc_off < OcTile; ++oc_off) {
    int oc_local = oc_tile_in_group * OcTile + oc_off;
    if (oc_local >= Cout_per_group) continue;
    int oc_global = g * Cout_per_group + oc_local;

    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      int p = p_idx[i];
      if (p >= P_total) continue;
      mY(oc_global, od_arr[i], oh_arr[i], ow_arr[i]) = static_cast<T>(acc[oc_off][i]);
    }
  }
}

torch::Tensor conv_transpose3d_forward(torch::Tensor x,
                                        torch::Tensor weight,
                                        c10::optional<torch::Tensor> bias,
                                        int stride, int padding, int output_padding,
                                        int dilation, int groups) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(weight.is_cuda(), "weight must be CUDA");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(weight.scalar_type() == at::kFloat, "weight must be float32");
  TORCH_CHECK(x.dim() == 5, "x must be [N, C, D, H, W]");
  TORCH_CHECK(weight.dim() == 5, "weight must be [Cin, Cout/groups, K, K, K]");

  int64_t N   = x.size(0);
  int64_t Cin = x.size(1);
  int64_t D   = x.size(2);
  int64_t H   = x.size(3);
  int64_t Win = x.size(4);

  int64_t Cout_per_group = weight.size(1);
  int64_t K = weight.size(2);
  TORCH_CHECK(weight.size(0) == Cin, "weight.size(0) must equal Cin");
  TORCH_CHECK(weight.size(3) == K && weight.size(4) == K, "kernel must be cubic");

  int64_t Cout = Cout_per_group * groups;

  TORCH_CHECK(stride > 0 && dilation > 0, "stride/dilation must be > 0");
  TORCH_CHECK(padding >= 0 && output_padding >= 0, "padding/output_padding must be >= 0");

  int64_t Dout = (D - 1) * stride - 2 * padding + dilation * (K - 1) + output_padding + 1;
  int64_t Hout = (H - 1) * stride - 2 * padding + dilation * (K - 1) + output_padding + 1;
  int64_t Wout = (Win - 1) * stride - 2 * padding + dilation * (K - 1) + output_padding + 1;
  TORCH_CHECK(Dout > 0 && Hout > 0 && Wout > 0, "Invalid output size computed");

  auto x_c = x.contiguous();
  auto w_c = weight.contiguous();

  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (bias.has_value()) {
    b_c = bias.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == Cout, "bias must be [Cout]");
    b_ptr = b_c.data_ptr<float>();
  }

  auto y = torch::empty({N, Cout, Dout, Hout, Wout}, x.options());

  constexpr int Threads = 256;
  constexpr int PVec    = 4;
  constexpr int OcTile  = 8;

  int64_t P_total = Dout * Hout * Wout;
  int64_t PTile   = Threads * PVec;

  int oc_tiles_per_group = (int)((Cout_per_group + OcTile - 1) / OcTile);
  int grid_y = groups * oc_tiles_per_group;

  dim3 block(Threads);
  dim3 grid(
      (unsigned)((P_total + PTile - 1) / PTile),
      (unsigned)grid_y,
      (unsigned)N
  );

  size_t shmem_bytes = (size_t)2 * OcTile * K * K * K * sizeof(float);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  conv_transpose3d_kernel<float><<<grid, block, shmem_bytes, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)N, (int)Cin, (int)D, (int)H, (int)Win,
      (int)Cout, (int)K,
      stride, stride, stride,
      padding, padding, padding,
      dilation, dilation, dilation,
      groups,
      (int)Dout, (int)Hout, (int)Wout
  );

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv_transpose3d_kernel launch failed: ", cudaGetErrorString(err));

  return y;
}
